class Solution {
public:
    int uniquePaths(int m, int n) {
        long long N = m + n - 2;
        long long k = min(m - 1, n - 1);
        long long res = 1;
        for (long long i = 1; i <= k; ++i) {
            res = res * (N - k + i) / i;
        }
        return (int)res;
    }
};

